package com.ruoyi.warehouse.finance;

import com.ruoyi.warehouse.support.*;
import java.math.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static com.ruoyi.warehouse.finance.FinanceWorkflowTest.*;

class FinanceAdjustmentTest {
    FinanceWorkflowTest f;FinanceAdjustmentService service;AdjustmentPolicyService policy;
    @BeforeEach void setup() throws Exception {f=new FinanceWorkflowTest();f.database();f.jdbc.execute("CREATE TABLE wh_order_billing(order_id VARCHAR(64),charge_id VARCHAR(64),source_snapshot VARCHAR(4000000),quote_json VARCHAR(4000000))");policy=new AdjustmentPolicyService(f.records,f.scope);service=new FinanceAdjustmentService(f.records,f.scope,f.rules,f.service,policy);}
    Map<String,Object> charge(String amount){return f.tx.execute(s->f.service.manualCharge(f.charge("client",amount)));}
    Map<String,Object> create(Map<String,Object> charge){return f.tx.execute(s->service.create(map("requestId",uuid(),"chargeId",charge.get("id"),"reason","Synthetic service review","evidenceRef","QA evidence")));}
    Map<String,Object> input(Map<String,Object> row,String component,String quantity,String decision){return map("_version",row.get("_version"),"decisions",List.of(map("component",component,"quantity",quantity,"decision",decision)),"reason","Synthetic verified correction","issueDate",LocalDate.now(ZoneOffset.UTC).toString(),"taxPointDate",LocalDate.now(ZoneOffset.UTC).toString(),"accountingPeriod",YearMonth.now(ZoneOffset.UTC).toString());}
    Map<String,Object> preview(Map<String,Object> row,Map<String,Object> input){return f.tx.execute(s->service.preview(text(row,"id"),input));}
    Map<String,Object> action(Map<String,Object> row,String action,Map<String,Object> extra){var in=map("requestId",uuid(),"_version",row.get("_version"),"action",action);in.putAll(extra);return f.tx.execute(s->service.action(text(row,"id"),in));}
    Map<String,Object> approve(Map<String,Object> row,Map<String,Object> input){var q=preview(row,input);return action(row,"approve",map("planInput",input,"quoteHash",q.get("quoteHash")));}
    Map<String,Object> execute(Map<String,Object> row){when(f.scope.actor()).thenReturn(8L);try{return action(row,"execute",Map.of());}finally{when(f.scope.actor()).thenReturn(7L);}}
    Map<String,Object> invoice(Map<String,Object> charge,boolean confirmed){var invoice=f.tx.execute(s->f.service.draft(map("requestId",uuid(),"client","client","chargeIds",List.of(charge.get("id")))));return confirmed?f.tx.execute(s->f.service.invoiceAction(text(invoice,"id"),map("requestId",uuid(),"_version",1,"action","confirm"))):invoice;}
    void configure(){var profile=map("name","SYNTHETIC ONLY","address","TEST ADDRESS","taxId","TEST ID");var p=map("version","qa-1","taxMethod","original-line-remainder-half-even","requireDifferentActor",true,"seller",profile,"buyers",Map.of("client",profile),"creditPrefix","QA-CN-");f.tx.execute(s->policy.save(map("requestId",uuid(),"_version",0,"policy",p)));}
    Map<String,Object> record(String kind,String id){return f.records.get(kind,id,false);}
    void amount(String expected,Object value){assertEquals(0,new BigDecimal(expected).compareTo(new BigDecimal(value.toString())));}
    long count(String table){return f.jdbc.queryForObject("SELECT COUNT(*) FROM "+table,Long.class);}
    Map<String,Object> syntheticComponents(){
        var lines=List.of(map("description","Goods in units","quantity",3,"rate","0.125","raw","375000000","amount","0.38","source","asn:units"));var data=map("client","client","warehouse","warehouse","description","Synthetic fractional receiving","source","synthetic-units","currency","GBP","status","UNCONFIRMED","amount","0.38","breakdown",lines);String id=uuid();f.record(id,"charges",data);f.jdbc.update("INSERT INTO wh_finance_source VALUES(?,?,?)","synthetic-units",id,WarehouseJson.write(map("quote",map("amount","0.38","lines",lines))));return record("charges",id);
    }
    @Test void unbilledReductionPreservesOriginalAndChangesOnlyFutureInvoiceBasis(){var charge=charge("10");var r=create(charge);r=execute(approve(r,input(r,"amount","3","reduce")));assertEquals("EXECUTED",r.get("status"));var after=record("charges",text(charge,"id"));amount("10",after.get("amount"));amount("7",after.get("billableAmount"));var invoice=invoice(after,false);amount("7",invoice.get("net"));amount("1.4",invoice.get("tax"));assertEquals(1,count("wh_finance_adjustment_effect"));assertEquals(0,count("wh_finance_credit_note"));}
    @Test void draftIsSupersededWithAllLinesAndClaimsRetained(){var a=charge("10");var b=charge("5");var old=f.tx.execute(s->f.service.draft(map("requestId",uuid(),"client","client","chargeIds",List.of(a.get("id"),b.get("id")))));var r=create(a);r=execute(approve(r,input(r,"amount","2","reduce")));var previous=record("invoices",text(old,"id"));var next=record("invoices",text(r,"replacementInvoice"));assertEquals("SUPERSEDED",previous.get("status"));amount("18",previous.get("amount"));amount("15.6",next.get("amount"));assertEquals(old.get("id"),next.get("predecessor"));assertEquals(4,count("wh_finance_invoice_line"));assertEquals(2,count("wh_finance_invoice_claim"));for(var charge:List.of(a,b))assertEquals(next.get("id"),record("charges",text(charge,"id")).get("invoice"));assertThrows(WarehouseException.class,()->f.tx.execute(s->f.service.invoiceAction(text(previous,"id"),map("requestId",uuid(),"_version",previous.get("_version"),"action","confirm"))));}
    @Test void confirmedCreditRequiresProfilesAndPreservesOriginalInvoiceTax(){var charge=charge("10");var old=invoice(charge,true);var r=create(charge);var in=input(r,"amount","2","reduce");assertThrows(WarehouseException.class,()->preview(r,in));configure();var done=execute(approve(r,in));var note=service.creditNote(text(done,"creditNote"));amount("2",note.get("net"));amount("0.4",note.get("tax"));amount("2.4",note.get("amount"));assertEquals("QA-CN-000001",note.get("number"));assertEquals(WarehouseJson.write(old),WarehouseJson.write(record("invoices",text(old,"id"))));assertThrows(WarehouseException.class,()->f.tx.execute(s->f.service.invoiceAction(text(old,"id"),map("requestId",uuid(),"_version",old.get("_version"),"action","unconfirm"))));}
    @Test void splittingCreditsCannotCreateOrLoseOriginalTax(){configure();var charge=charge("0.03");invoice(charge,true);BigDecimal net=BigDecimal.ZERO,tax=BigDecimal.ZERO;for(int i=0;i<3;i++){var r=create(charge);var done=execute(approve(r,input(r,"amount","0.01","reduce")));var note=service.creditNote(text(done,"creditNote"));net=net.add(new BigDecimal(note.get("net").toString()));tax=tax.add(new BigDecimal(note.get("tax").toString()));}amount("0.03",net);amount("0.01",tax);var r=create(charge);assertThrows(WarehouseException.class,()->preview(r,input(r,"amount","0.01","reduce")));}
    @Test void quantityReductionsUseRawRemaindersAndDoNotDrift(){var charge=syntheticComponents();var values=new ArrayList<String>();for(int i=0;i<3;i++){var r=create(charge);var in=input(r,"line-0","1","reduce");var plan=AdjustmentSupport.map(preview(r,in).get("plan"));values.add(new BigDecimal(plan.get("net").toString()).toPlainString());execute(approve(r,in));}assertEquals(List.of("0.13","0.13","0.12"),values);amount("0",record("charges",text(charge,"id")).get("billableAmount"));}
    @Test void unitsCannotBecomeFractionalAndOriginalRatesCannotBeSubmitted(){var r=create(syntheticComponents());assertThrows(WarehouseException.class,()->preview(r,input(r,"line-0","0.5","reduce")));var in=input(r,"line-0","1","reduce");in.put("rate",999);assertThrows(WarehouseException.class,()->preview(r,in));}
    @Test void approvalReservesFeeAndRevokeRestoresInvoicing(){var charge=charge("10");var r=create(charge);r=approve(r,input(r,"amount","1","reduce"));assertThrows(WarehouseException.class,()->invoice(charge,false));var other=create(charge);assertThrows(WarehouseException.class,()->preview(other,input(other,"amount","1","reduce")));r=action(r,"revoke",map("reason","Rechecking source"));assertEquals("REVIEW",r.get("status"));assertEquals(0,count("wh_finance_adjustment_lock"));invoice(charge,false);}
    @Test void reservingOneInvoiceLineFreezesConfirmAndUnconfirm(){var charge=charge("10");var invoice=invoice(charge,false);var r=create(charge);approve(r,input(r,"amount","1","reduce"));for(String action:List.of("confirm","unconfirm"))assertThrows(WarehouseException.class,()->f.tx.execute(s->f.service.invoiceAction(text(invoice,"id"),map("requestId",uuid(),"_version",invoice.get("_version"),"action",action))));}
    @Test void executionRequiresDifferentActorByDefault(){var r=create(charge("10"));var approved=approve(r,input(r,"amount","1","reduce"));assertThrows(WarehouseException.class,()->action(approved,"execute",Map.of()));execute(approved);}
    @Test void changedPolicyInvalidatesApprovalUntilRevokedAndReviewed(){configure();var r=create(charge("10"));r=approve(r,input(r,"amount","1","reduce"));var p=AdjustmentSupport.map(policy.get().get("policy"));p.put("version","qa-2");f.tx.execute(s->policy.save(map("requestId",uuid(),"_version",1,"policy",p)));var approved=r;assertThrows(WarehouseException.class,()->execute(approved));assertEquals(1,count("wh_finance_adjustment_lock"));assertEquals(0,count("wh_finance_adjustment_effect"));}
    @Test void retainedDecisionNeedsExplicitReconsiderationAndPreservesHistory(){var charge=charge("10");var r=create(charge);var retained=execute(approve(r,input(r,"amount","3","retain")));assertEquals("RETAINED",retained.get("status"));var second=create(charge);var in=input(second,"amount","2","reduce");assertThrows(WarehouseException.class,()->preview(second,in));in.put("reconsiderationOf",List.of(retained.get("effectId")));in.put("reconsiderationReason","New verified service evidence");execute(approve(second,in));assertEquals("RETAINED",record("adjustments",text(retained,"id")).get("status"));amount("8",record("charges",text(charge,"id")).get("billableAmount"));}
    @Test void zeroFeeCanBeRetainedButCannotBecomeACashCredit(){var r=create(charge("0"));assertThrows(WarehouseException.class,()->preview(r,input(r,"amount","0","reduce")));assertEquals("RETAINED",execute(approve(r,input(r,"amount","0","retain"))).get("status"));assertEquals(0,count("wh_finance_credit_note"));}
    @Test void failedCreditPostingRollsBackEffectsNumberAndApprovalConsumption(){configure();var charge=charge("10");invoice(charge,true);var r=create(charge);var approved=approve(r,input(r,"amount","1","reduce"));f.jdbc.execute("ALTER TABLE wh_finance_credit_note ADD CONSTRAINT fail_note CHECK(number='REJECT_ALL')");assertThrows(RuntimeException.class,()->execute(approved));assertEquals(0,count("wh_finance_adjustment_effect"));assertEquals(0,count("wh_finance_credit_sequence"));assertEquals(1,count("wh_finance_adjustment_lock"));assertEquals("APPROVED",record("adjustments",text(r,"id")).get("status"));assertNull(record("charges",text(charge,"id")).get("adjustedAmount"));f.jdbc.execute("ALTER TABLE wh_finance_credit_note DROP CONSTRAINT fail_note");var done=execute(approved);assertEquals("QA-CN-000001",service.creditNote(text(done,"creditNote")).get("number"));}
    @Test void executionExactRetryDoesNotPostAgainAndChangedPayloadConflicts(){var r=create(charge("10"));var approved=approve(r,input(r,"amount","1","reduce"));when(f.scope.actor()).thenReturn(8L);var body=map("requestId",uuid(),"_version",approved.get("_version"),"action","execute");var first=f.tx.execute(s->service.action(text(r,"id"),body));assertEquals(WarehouseJson.write(first),WarehouseJson.write(f.tx.execute(s->service.action(text(r,"id"),body))));body.put("reason","Different request");assertThrows(WarehouseException.class,()->f.tx.execute(s->service.action(text(r,"id"),body)));assertEquals(1,count("wh_finance_adjustment_effect"));}
    @Test void concurrentApprovalCanReserveOriginalFeeOnlyOnce() throws Exception {var charge=charge("10");var a=create(charge);var b=create(charge);var ia=input(a,"amount","8","reduce");var ib=input(b,"amount","8","reduce");var qa=preview(a,ia);var qb=preview(b,ib);var pool=Executors.newFixedThreadPool(2);try{var tasks=List.<Callable<Boolean>>of(()->{try{action(a,"approve",map("planInput",ia,"quoteHash",qa.get("quoteHash")));return true;}catch(RuntimeException e){return false;}},()->{try{action(b,"approve",map("planInput",ib,"quoteHash",qb.get("quoteHash")));return true;}catch(RuntimeException e){return false;}});int success=0;for(var result:pool.invokeAll(tasks))if(result.get())success++;assertEquals(1,success);assertEquals(1,count("wh_finance_adjustment_lock"));}finally{pool.shutdownNow();}}
    @Test void changedOriginalEvidenceAndTamperedEffectsAreRejected(){var charge=charge("10");var r=create(charge);execute(approve(r,input(r,"amount","1","reduce")));f.jdbc.update("UPDATE wh_finance_adjustment_effect SET effect_hash=REPEAT('0',64)");assertThrows(WarehouseException.class,()->f.tx.execute(s->service.source(text(charge,"id"))));}
    @Test void cancelledRequestCannotBeApprovedOrAlterFee(){var charge=charge("10");var r=create(charge);var cancelled=action(r,"cancel",map("reason","Incorrect request"));assertThrows(WarehouseException.class,()->preview(cancelled,input(cancelled,"amount","1","reduce")));assertEquals(0,count("wh_finance_adjustment_effect"));amount("10",record("charges",text(charge,"id")).get("amount"));}

    @Test void repeatedDraftReissuesKeepCompleteLineSnapshotsAndCanThenBeCredited(){configure();var charge=charge("10");var first=invoice(charge,false);String latest=text(first,"id");for(int i=0;i<2;i++){var r=create(charge);var done=execute(approve(r,input(r,"amount","1","reduce")));latest=text(done,"replacementInvoice");var frozen=WarehouseJson.map(f.jdbc.queryForObject("SELECT snapshot_json FROM wh_finance_invoice_line WHERE invoice_id=? AND charge_id=?",String.class,latest,charge.get("id")));assertEquals(latest,AdjustmentSupport.map(frozen.get("charge")).get("invoice"));}var last=record("invoices",latest);amount("8",last.get("net"));f.tx.execute(s->f.service.invoiceAction(text(last,"id"),map("requestId",uuid(),"_version",last.get("_version"),"action","confirm")));var r=create(charge);var done=execute(approve(r,input(r,"amount","3","reduce")));amount("3",service.creditNote(text(done,"creditNote")).get("net"));amount("5",f.tx.execute(s->service.source(text(charge,"id"))).get("remainingNet"));assertEquals("SUPERSEDED",record("invoices",text(first,"id")).get("status"));}
    @Test void originalInvoiceVatAndCurrencySurviveNewClientSettings(){configure();var charge=charge("10");invoice(charge,true);var client=record("clients","client");var data=FinanceInput.business(client);data.put("currency","USD");data.put("serviceVatRate",5);f.tx.execute(s->f.records.write("clients","client",data,((Number)client.get("_version")).longValue(),"client",""));var r=create(charge);var done=execute(approve(r,input(r,"amount","2","reduce")));var note=service.creditNote(text(done,"creditNote"));assertEquals("GBP",note.get("currency"));amount("20",note.get("vatRate"));amount("0.4",note.get("tax"));}
    @Test void labourHoursKeepThreeDecimalsAndRejectExtraPrecision(){var c=syntheticComponents();var lines=List.of(map("description","ASN labour hours","source","asn:hours","quantity","0.003","rate","125","raw","375000000","amount","0.38"));f.jdbc.update("UPDATE wh_record SET business_json=? WHERE id=?",WarehouseJson.write(map("client","client","warehouse","warehouse","description","Synthetic labour","source","synthetic-units","currency","GBP","status","UNCONFIRMED","amount","0.38","breakdown",lines)),c.get("id"));f.jdbc.update("UPDATE wh_finance_source SET evidence_json=? WHERE charge_id=?",WarehouseJson.write(map("quote",map("amount","0.38","lines",lines))),c.get("id"));var r=create(c);assertThrows(WarehouseException.class,()->preview(r,input(r,"line-0","0.0001","reduce")));execute(approve(r,input(r,"line-0","0.001","reduce")));amount("0.25",record("charges",text(c,"id")).get("billableAmount"));}
    @Test void futureInvoiceWarehouseScopeAlsoRestrictsExistingRequests(){var charge=charge("10");var r=create(charge);f.record("hidden","warehouses",map("name","Hidden"));var input=f.charge("client","4");input.put("warehouse","hidden");var other=f.tx.execute(s->f.service.manualCharge(input));f.tx.execute(s->f.service.draft(map("requestId",uuid(),"client","client","chargeIds",List.of(charge.get("id"),other.get("id")))));try(var security=mockStatic(com.ruoyi.common.utils.SecurityUtils.class)){security.when(()->com.ruoyi.common.utils.SecurityUtils.hasPermi(anyString())).thenReturn(true);when(f.scope.admin()).thenReturn(false);f.jdbc.update("INSERT INTO wh_user_scope VALUES(7,'WAREHOUSE','warehouse')");assertEquals(0L,service.list("adjustments",1,20,"client").get("total"));f.jdbc.update("INSERT INTO wh_user_scope VALUES(7,'WAREHOUSE','hidden')");assertEquals(1L,service.list("adjustments",1,20,"client").get("total"));}}
    @Test void replayStillRequiresCurrentActionPermission(){var r=create(charge("10"));var approved=approve(r,input(r,"amount","1","reduce"));when(f.scope.actor()).thenReturn(8L);var input=map("requestId",uuid(),"_version",approved.get("_version"),"action","execute");f.tx.execute(s->service.action(text(r,"id"),input));when(f.scope.admin()).thenReturn(false);try(var security=mockStatic(com.ruoyi.common.utils.SecurityUtils.class)){security.when(()->com.ruoyi.common.utils.SecurityUtils.hasPermi(anyString())).thenReturn(false);assertThrows(WarehouseException.class,()->f.tx.execute(s->service.action(text(r,"id"),input)));assertEquals(1,count("wh_finance_adjustment_effect"));}}
    @Test void creditNoteChecksumPreventsPrintingTamperedAmount(){configure();var c=charge("10");invoice(c,true);var r=create(c);var done=execute(approve(r,input(r,"amount","1","reduce")));String id=text(done,"creditNote");var n=FinanceInput.business(record("creditNotes",id));n.put("amount",999);f.jdbc.update("UPDATE wh_record SET business_json=? WHERE id=?",WarehouseJson.write(n),id);assertThrows(WarehouseException.class,()->service.creditNote(id));}
    @Test void policyRequiresExplicitSeparationAndVersionChanges(){configure();var p=AdjustmentSupport.map(policy.get().get("policy"));p.remove("requireDifferentActor");assertThrows(WarehouseException.class,()->f.tx.execute(s->policy.save(map("requestId",uuid(),"_version",1,"policy",p))));p.put("requireDifferentActor",false);assertThrows(WarehouseException.class,()->f.tx.execute(s->policy.save(map("requestId",uuid(),"_version",1,"policy",p))));p.put("version","qa-2");f.tx.execute(s->policy.save(map("requestId",uuid(),"_version",1,"policy",p)));}
    @Test void maximumMoneyPrecisionIsNotRejectedByInternalNineDecimalPadding(){var c=charge("1000000000000000000000.25");var r=create(c);execute(approve(r,input(r,"amount","0.01","reduce")));amount("1000000000000000000000.24",f.tx.execute(s->service.source(text(c,"id"))).get("remainingNet"));var second=create(c);execute(approve(second,input(second,"amount","0.01","reduce")));amount("1000000000000000000000.23",f.tx.execute(s->service.source(text(c,"id"))).get("remainingNet"));}
}